Adjuster Web Application.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Adjuster Web Application container

Container_Boundary(adjuster_web_application, "Adjuster Web Application") {
    Component(Claims_UI_Router, "Claims UI Router", "React Router", "Manages client-side routing and navigation for multi-tab adjuster workflows.")
    Component(Claims_Dashboard_Component, "Claims Dashboard Component", "React / TypeScript", "Renders high-performance UI components for managing and viewing claims data.")
    Component(API_Client_Module, "API Client Module", "Axios / Fetch API", "Communicates securely with the Backend-For-Frontend container via HTTPS.")
}

Rel(Claims_UI_Router, Claims_Dashboard_Component, "Loads view")
Rel(Claims_Dashboard_Component, API_Client_Module, "Requests claims data")

@enduml

Routing Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(routing_container, "Routing Container") {
    Component(Routing_Service, "Routing Service", "Go", "Handles high-performance network routing of claims traffic and low memory footprint operations.")
    Component(mTLS_Enforcer, "mTLS Enforcer", "mTLS / Azure Key Vault", "Enforces strict bidirectional TLS with certificate pinning and secures private keys for hybrid bridging.")
    Component(GitOps_Sync_Agent, "GitOps Sync Agent", "ArgoCD / Git", "Synchronizes routing tables via GitOps configuration pipeline for rapid claim type rollbacks.")
}

Rel(Routing_Service, mTLS_Enforcer, "Secures traffic sent to the COBOL/DB2 Mainframe", "mTLS")
Rel(GitOps_Sync_Agent, Routing_Service, "Updates routing configuration", "Git")
@enduml
